#[inline]
pub unsafe fn choices_fread(
    mut c: *mut choices_t,
    mut file: *mut FILE,
    mut input_delimiter: c_char,
) {
    let buffer_start: size_t = (*c).buffer_size;
    let mut size: size_t = buffer_start;
    let mut capacity: size_t = INITIAL_BUFFER_CAPACITY as size_t;

    while capacity <= size {
        capacity = capacity.wrapping_mul(2 as size_t);
    }

    (*c).buffer = safe_realloc((*c).buffer as *mut c_void, capacity) as *mut c_char;
    let mut buffer: *mut c_char = (*c).buffer;

    loop {
        size = size.wrapping_add(fread(
            buffer.offset(size as isize) as *mut c_void,
            1 as size_t,
            capacity.wrapping_sub(size),
            file,
        ));
        if size != capacity {
            break;
        }
        capacity = capacity.wrapping_mul(2 as size_t);
        buffer = safe_realloc(buffer as *mut c_void, capacity) as *mut c_char;
        (*c).buffer = buffer;
    }

    buffer = safe_realloc(buffer as *mut c_void, size.wrapping_add(1 as size_t)) as *mut c_char;
    (*c).buffer = buffer;
    (*c).buffer_size = size.wrapping_add(1 as size_t);
    *buffer.offset(size as isize) = '\0' as i32 as c_char;

    let line_end: *mut c_char = buffer.offset((*c).buffer_size as isize);
    let mut line: *mut c_char = buffer.offset(buffer_start as isize);

    while line < line_end {
        let mut nl: *mut c_char = strchr(line, input_delimiter as c_int);
        if !nl.is_null() {
            *nl = '\0' as i32 as c_char;
            nl = nl.offset(1);
        }

        if *line != 0 {
            choices_add(c, line);
        }

        if nl.is_null() || nl >= line_end {
            break;
        }
        line = nl;
    }
}

